={{ 
(() => {
  const raw = $json.parameters0 ?? $fromAI('parameters0', 'JSON payload для поиска товара в Supabase', 'string');

  let obj;

  try {
    obj = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    obj = {
      query: String(raw || '').trim()
    };
  }

  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
    obj = {
      query: String(raw || '').trim()
    };
  }

  // Если агент прислал { parameters0: "{...}" }
  if (obj.parameters0) {
    try {
      obj = typeof obj.parameters0 === 'string'
        ? JSON.parse(obj.parameters0)
        : obj.parameters0;
    } catch (e) {
      obj = {
        query: String(obj.parameters0 || '').trim()
      };
    }
  }

  // Новая таблица
  obj.table = 'gadget_bar_products_1c';
  obj.source_table = 'gadget_bar_products_1c';

  // filters -> filter
  if (!obj.filter && obj.filters && typeof obj.filters === 'object') {
    obj.filter = obj.filters;
  }
  delete obj.filters;

  // select -> fields
  if ((!obj.fields || !Array.isArray(obj.fields)) && Array.isArray(obj.select)) {
    obj.fields = obj.select;
  }
  delete obj.select;

  if (!obj.filter || typeof obj.filter !== 'object' || Array.isArray(obj.filter)) {
    obj.filter = {};
  }

  const f = obj.filter;

  // Общий текст для анализа
  const qRaw = String(obj.query || '');
  const nRaw = String(f.name_contains || '');
  const bRaw = String(f.brand_contains || '');
  const combinedRaw = `${qRaw} ${nRaw} ${bRaw}`.trim();
  const combined = combinedRaw.toLowerCase();

  // Определяем аксессуар
  const isAccessory =
    /чехол|чехлы|стекло|стёкл|пленк|плёнк|ремеш|ремень|кабель|зарядк|адаптер|блок питания|powerbank|повербанк|держатель|lens protector|case|strap|glass/i.test(combinedRaw);

  // -----------------------------
  // 1. Старые категории -> новая таблица
  // -----------------------------

  if (
    String(f.category || '').toLowerCase() === 'apple' &&
    String(f.subcategory || '').toLowerCase() === 'iphone'
  ) {
    f.category = 'Устройства';
    f.subcategory = 'Смартфон';
    f.brand_contains = f.brand_contains || 'Apple';
  }

  if (String(f.category || '').toLowerCase() === 'samsung') {
    const sub = String(f.subcategory || '').toLowerCase();

    f.category = 'Устройства';
    f.brand_contains = f.brand_contains || 'Samsung';

    if (sub.includes('смартфон')) {
      f.subcategory = 'Смартфон';
    } else if (sub.includes('планшет')) {
      f.subcategory = 'Планшет';
    } else if (sub.includes('watch') || sub.includes('часы')) {
      f.subcategory = 'Умные часы';
    } else if (sub.includes('науш')) {
      f.subcategory = 'Наушники';
    }
  }

  if (f.category === 'Смартфон') {
    f.category = 'Устройства';
    f.subcategory = f.subcategory || 'Смартфон';
  }

  if (f.category === 'Планшет') {
    f.category = 'Устройства';
    f.subcategory = f.subcategory || 'Планшет';
  }

  if (f.category === 'Наушники') {
    f.category = 'Устройства';
    f.subcategory = f.subcategory || 'Наушники';
  }

  if (f.category === 'Умные часы') {
    f.category = 'Устройства';
    f.subcategory = f.subcategory || 'Умные часы';
  }

  // -----------------------------
  // 2. Samsung S/A/Z как устройство
  // -----------------------------
  // Если клиент пишет "с26", "S26", "c26", "Samsung S26", но НЕ аксессуар,
  // значит ищем смартфон Samsung, а не чехлы/стёкла.

  const samsungModelMatch = combinedRaw.match(/(?:samsung\s+)?(?:galaxy\s+)?([sсcаa])\s?(\d{2})(?:\s*(ultra|plus|fe))?/i);

  if (samsungModelMatch && !isAccessory) {
    const seriesRaw = samsungModelMatch[1].toLowerCase();
    const num = samsungModelMatch[2];
    const suffixRaw = samsungModelMatch[3];

    let series = 'S';

    if (seriesRaw === 'а' || seriesRaw === 'a') {
      series = 'A';
    }

    if (seriesRaw === 's' || seriesRaw === 'с' || seriesRaw === 'c') {
      series = 'S';
    }

    let suffix = '';
    if (suffixRaw) {
      const s = suffixRaw.toLowerCase();
      if (s === 'ultra') suffix = ' Ultra';
      if (s === 'plus') suffix = ' Plus';
      if (s === 'fe') suffix = ' FE';
    }

    const model = `${series}${num}${suffix}`;

    f.category = 'Устройства';
    f.subcategory = 'Смартфон';
    f.brand_contains = 'Samsung';
    f.name_contains = model;

    obj.query = `Samsung Galaxy ${model}`;
  }

  // Samsung Fold / Flip
  if (!isAccessory && /z\s*fold|з\s*фолд|galaxy\s*fold/i.test(combinedRaw)) {
    f.category = 'Устройства';
    f.subcategory = 'Смартфон';
    f.brand_contains = 'Samsung';
    f.name_contains = 'Fold';
    obj.query = 'Samsung Galaxy Z Fold';
  }

  if (!isAccessory && /z\s*flip|з\s*флип|galaxy\s*flip/i.test(combinedRaw)) {
    f.category = 'Устройства';
    f.subcategory = 'Смартфон';
    f.brand_contains = 'Samsung';
    f.name_contains = 'Flip';
    obj.query = 'Samsung Galaxy Z Flip';
  }

  // -----------------------------
  // 3. iPhone как устройство
  // -----------------------------
  // Если клиент спрашивает iPhone и это НЕ аксессуар — ищем смартфон Apple.

  const iphoneMatch = combinedRaw.match(/iphone\s*(\d{1,2})(?:\s*(pro\s*max|pro|max|plus|air|e|se))?/i);

  if (iphoneMatch && !isAccessory) {
    const gen = iphoneMatch[1];
    const rawType = String(iphoneMatch[2] || '').toLowerCase().replace(/\s+/g, ' ');

    let type = '';
    if (rawType === 'pro max' || rawType === 'max') type = ' Pro Max';
    else if (rawType === 'pro') type = ' Pro';
    else if (rawType === 'plus') type = ' Plus';
    else if (rawType === 'air') type = ' Air';
    else if (rawType === 'e') type = 'e';
    else if (rawType === 'se') type = ' SE';

    const model = `iPhone ${gen}${type}`;

    f.category = 'Устройства';
    f.subcategory = 'Смартфон';
    f.brand_contains = 'Apple';
    f.name_contains = model;

    obj.query = model;
  }

  // -----------------------------
  // 4. Аксессуары
  // -----------------------------
  // Если аксессуар — Apple/Samsung/Xiaomi и т.п. не бренд товара,
  // а совместимое устройство. Убираем brand_contains устройства.

  if (isAccessory) {
    f.category = 'Аксессуары';

    if (/чехол|чехлы|case/i.test(combinedRaw)) {
      f.subcategory = 'Чехлы';
    } else if (/стекло|стёкл|пленк|плёнк|lens protector|glass/i.test(combinedRaw)) {
      f.subcategory = 'Стекла';
    } else if (/кабель/i.test(combinedRaw)) {
      f.subcategory = 'Кабель';
    } else if (/зарядк|адаптер|блок питания/i.test(combinedRaw)) {
      f.subcategory = 'Адаптер питания';
    } else if (/powerbank|повербанк/i.test(combinedRaw)) {
      f.subcategory = 'PowerBank';
    } else if (/ремеш|ремень|strap/i.test(combinedRaw)) {
      f.subcategory = 'Ремень';
    } else if (/переходник/i.test(combinedRaw)) {
      f.subcategory = 'Переходник';
    }

    const brand = String(f.brand_contains || '').toLowerCase();

    if (['apple', 'samsung', 'xiaomi', 'honor', 'huawei', 'realme', 'tecno', 'oneplus'].includes(brand)) {
      delete f.brand_contains;
    }

    // Для аксессуаров оставляем в name_contains модель совместимого устройства
    const samsungAccMatch = combinedRaw.match(/(?:samsung\s+)?(?:galaxy\s+)?([sсcаa])\s?(\d{2})(?:\s*(ultra|plus|fe))?/i);
    if (samsungAccMatch) {
      const seriesRaw = samsungAccMatch[1].toLowerCase();
      const num = samsungAccMatch[2];
      const suffixRaw = samsungAccMatch[3];

      let series = (seriesRaw === 'а' || seriesRaw === 'a') ? 'A' : 'S';

      let suffix = '';
      if (suffixRaw) {
        const s = suffixRaw.toLowerCase();
        if (s === 'ultra') suffix = ' Ultra';
        if (s === 'plus') suffix = ' Plus';
        if (s === 'fe') suffix = ' FE';
      }

      f.name_contains = `${series}${num}${suffix}`;
    }

    const iphoneAccMatch = combinedRaw.match(/iphone\s*(\d{1,2})(?:\s*(pro\s*max|pro|max|plus|air|e|se))?/i);
    if (iphoneAccMatch) {
      const gen = iphoneAccMatch[1];
      const rawType = String(iphoneAccMatch[2] || '').toLowerCase().replace(/\s+/g, ' ');

      let type = '';
      if (rawType === 'pro max' || rawType === 'max') type = ' Pro Max';
      else if (rawType === 'pro') type = ' Pro';
      else if (rawType === 'plus') type = ' Plus';
      else if (rawType === 'air') type = ' Air';
      else if (rawType === 'e') type = 'e';
      else if (rawType === 'se') type = ' SE';

      f.name_contains = `iPhone ${gen}${type}`;
    }
  }


  // -----------------------------
  // 4.5. Workaround под новую таблицу и текущую Edge Function
  // -----------------------------
  // В новой таблице бренд хранится в manufacturer, но Edge Function может
  // старой логикой обрабатывать brand_contains не там. Если уже есть точный
  // category + subcategory + name_contains, бренд не нужен для RPC и может дать пустой результат.
  if (
    f.category === 'Устройства' &&
    f.subcategory &&
    f.name_contains &&
    f.brand_contains
  ) {
    delete f.brand_contains;
  }

  // Если query слишком общий ("iPhone"), а name_contains точнее ("iPhone 17"),
  // отправляем в query точную модель. Это повышает качество поиска и логов.
  if (
    f.name_contains &&
    (
      !obj.query ||
      String(obj.query).trim() === '' ||
      String(obj.query).trim().length < String(f.name_contains).trim().length
    )
  ) {
    obj.query = String(f.name_contains).trim();
  }

  // Нормализация города для downstream-агентов: поля city_availability нужны
  // при любой явной локации в запросе.
  if (/воронеж|ярослав|краснодар|казан|уф[аеу]?|перм|липецк|белгород|ростов|тамбов|ижевск/i.test(combinedRaw)) {
    if (!Array.isArray(obj.fields)) obj.fields = [];
    if (!obj.fields.includes('city_availability')) obj.fields.push('city_availability');
  }


  // -----------------------------
  // 5. Fields
  // -----------------------------

  if (!obj.fields || !Array.isArray(obj.fields) || obj.fields.length === 0) {
    obj.fields = [
      'id',
      'name',
      'price',
      'availability',
      'url',
      'available_in_cities',
      'total_stock'
    ];
  }

  const allowedFields = new Set([
    'id',
    'product_id',
    'variant_id',
    'name',
    'product_name',
    'offer_name',
    'price',
    'currency',
    'availability',
    'total_stock',
    'available_in_cities',
    'city_availability',
    'category',
    'subcategory',
    'group_id',
    'group_name',
    'manufacturer',
    'description',
    'url',
    'image_url',
    'images',
    'characteristics',
    'metadata',
    'content',
    'created_at_1c',
    'updated_at'
  ]);

  obj.fields = obj.fields.filter(field => allowedFields.has(field));

  if (obj.fields.length === 0) {
    obj.fields = [
      'id',
      'name',
      'price',
      'availability',
      'url',
      'available_in_cities',
      'total_stock'
    ];
  }

  // -----------------------------
  // 6. Query fallback
  // -----------------------------

  if (!obj.query || String(obj.query).trim() === '') {
    if (f.name_contains) {
      obj.query = String(f.name_contains).trim();
    } else if (f.brand_contains) {
      obj.query = String(f.brand_contains).trim();
    }
  }

  if (
    (!obj.query || String(obj.query).trim() === '') &&
    (!f.name_contains || String(f.name_contains).trim() === '') &&
    (!f.brand_contains || String(f.brand_contains).trim() === '')
  ) {
    obj.query = 'товар';
  }

  // -----------------------------
  // 7. Limit / ranking
  // -----------------------------

  if (!obj.limit || Number(obj.limit) <= 0) {
    obj.limit = 40;
  }

  if (!obj.ranking || typeof obj.ranking !== 'object') {
    obj.ranking = {};
  }

  if (typeof obj.ranking.availability_boost === 'undefined') {
    obj.ranking.availability_boost = true;
  }

  return JSON.stringify(obj);
})()
}}

